<h1>کاربران</h1><a class="primary" href="<?= $this->h($this->url('/users/new')) ?>">افزودن کاربر / صاحب تجربه</a><form method="get" class="search section"><input type="hidden" name="r" value="/users"><label class="sr-only" for="q">جست‌وجوی کاربر</label><input id="q" name="q" value="<?= $this->h($query) ?>" placeholder="نام، شماره یا شناسه داخلی"><button class="primary">جست‌وجو</button></form><div class="records section"><?php foreach($rows as $row): ?><article class="card"><h2><?= $this->h($row['display_name']?:'نام تنظیم نشده') ?></h2><p class="ltr"><?= $this->h($row['phone']??'شماره ثبت نشده') ?></p><p class="small ltr">ID: <?= $this->h($row['id']) ?></p><span class="tag"><?= !empty($row['deleted_at'])?'حذف‌شده':($row['status']==='active'?'فعال':'محدودشده') ?></span><?php if($row['id']!==$this->actor['user_id']): ?><?php if(empty($row['deleted_at'])): ?><?= $this->start('/users/status') ?><input type="hidden" name="id" value="<?= $this->h($row['id']) ?>"><input type="hidden" name="status" value="<?= $row['status']==='active'?'blocked':'active' ?>"><?= $this->field('current_password','رمز فعلی مدیر برای این تغییر','password') ?><button class="secondary"><?= $row['status']==='active'?'محدودکردن حساب و بستن نشست‌ها':'فعال‌کردن حساب' ?></button></form><?php endif; ?><?= $this->start(!empty($row['deleted_at'])?'/users/restore':'/users/delete') ?><input type="hidden" name="id" value="<?= $this->h($row['id']) ?>"><?= $this->field('current_password','رمز فعلی مدیر','password') ?><button class="secondary"><?= !empty($row['deleted_at'])?'بازیابی کاربر':'حذف قابل‌بازیابی و بستن دسترسی' ?></button></form><?php endif; ?></article><?php endforeach; ?><?php if(!$rows): ?><p class="empty card">کاربری مطابق جست‌وجو پیدا نشد.</p><?php endif; ?></div><nav class="row section" aria-label="صفحه‌بندی"><?php if($page>1): ?><a class="secondary" href="/index.php?r=%2Fusers&amp;page=<?= $page-1 ?>&amp;q=<?= $this->h(rawurlencode($query)) ?>">قبلی</a><?php endif; ?><span>صفحه <?= $this->h($page) ?></span><?php if($more): ?><a class="secondary" href="/index.php?r=%2Fusers&amp;page=<?= $page+1 ?>&amp;q=<?= $this->h(rawurlencode($query)) ?>">بعدی</a><?php endif; ?></nav>
